<script>
(()=>{const btn=document.getElementById('getGps'),submit=document.getElementById('submitCheckin'),status=document.getElementById('gpsStatus');if(!btn)return;function newKey(){if(window.crypto&&crypto.randomUUID)return crypto.randomUUID();return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g,c=>{const r=Math.random()*16|0;return(c==='x'?r:(r&3|8)).toString(16)});}document.getElementById('idem').value=newKey();btn.addEventListener('click',()=>{if(!('geolocation' in navigator)){status.className='alert error';status.textContent='Browser tidak mendukung GPS. Gunakan browser modern dan aktifkan lokasi.';return;}status.className='alert';status.textContent='Sedang mengambil lokasi GPS…';btn.disabled=true;navigator.geolocation.getCurrentPosition(pos=>{document.getElementById('lat').value=pos.coords.latitude;document.getElementById('lon').value=pos.coords.longitude;document.getElementById('accuracy').value=pos.coords.accuracy;status.className='alert';status.textContent='Lokasi berhasil diperoleh. Akurasi yang dilaporkan perangkat: ±'+Math.round(pos.coords.accuracy)+' meter. Periksa catatan jika diperlukan, lalu konfirmasi.';submit.disabled=false;btn.disabled=false;},err=>{status.className='alert error';let msg=err.code===1?'Izin lokasi ditolak. Aktifkan izin lokasi untuk situs ini melalui pengaturan browser.':err.code===2?'Lokasi tidak tersedia. Pastikan GPS/lokasi perangkat aktif.':'Permintaan lokasi terlalu lama. Coba lagi di area dengan sinyal GPS lebih baik.';status.textContent=msg;btn.disabled=false;submit.disabled=true;},{enableHighAccuracy:true,timeout:20000,maximumAge:0});});document.getElementById('checkinForm').addEventListener('submit',()=>{submit.disabled=true;submit.textContent='Menyimpan check-in…';});})();
</script>
